#!/usr/bin/env python3
"""
===============================================================================
 macOSLAPS | Docs | gen-settings-doc.py
===============================================================================
 Version:   4.0.0
 Author:    Joshua D. Miller, Claude
 Created:   2026-11-12
 Updated:   2026-11-12

 Purpose:
     Writes docs/settings.md, the settings reference on the docs site,
     from the Jamf Pro custom schema in "Profile Manifests/", so the page
     always lists the same keys, defaults and values as the manifests.
     CI fails if the committed page differs from what this prints.

 Usage:
     python3 .github/scripts/gen-settings-doc.py           # write the page
     python3 .github/scripts/gen-settings-doc.py --check   # fail if stale
===============================================================================
 CHANGELOG
===============================================================================
 Version   Date         Author    Description
 -------   ----------   -------   --------------------------------------------
 4.0.0     2026-11-12   joshua    New file.
                        claude
===============================================================================
"""

import json
import pathlib
import re
import sys

# ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: #
# ------------ #
# | Sections | #
# ------------ #
# Which keys go under which heading, in manifest order. A key missing     #
# here fails the run, so a new setting can't be left off the page.        #
ROOT = pathlib.Path(__file__).resolve().parents[2]
SCHEMA = ROOT / "Profile Manifests" / "com.joshua-d-miller.macoslaps.json"
PAGE = ROOT / "docs" / "settings.md"

SECTIONS = [
    ("Account and method", ["LocalAdminAccount", "Method",
                            "DaysTillExpiration", "FirstPass",
                            "RemoveKeychain"]),
    ("Password", ["PasswordStyle", "PasswordLength", "PasswordGrouping",
                  "PasswordSeparator", "RemovePassChars", "ExclusionSets",
                  "PasswordRequirements"]),
    ("Escrow and inventory", ["EscrowCertificates", "StagedRotation",
                              "EscrowConfirmations", "InventoryHook",
                              "InventoryHookCommand",
                              "InventoryHookConfirms"]),
    ("Device mode", ["RetrievalMode", "RevealGracePeriod", "RevealAction",
                     "ADRevealCode"]),
    ("Admin group protection", ["ApprovedAdmins", "AdminGroupPolicy",
                                "AllowMDMManagedAccount"]),
    ("Active Directory", ["ADSchema", "PreferredDC"]),
]


# ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: #
# -------------- #
# | Formatting | #
# -------------- #
# One table row per key: name, type, default, allowed values, meaning.    #
def type_of(prop):
    kind = prop["type"]
    if kind == "array":
        return "array of " + prop.get("items", {}).get("type", "string")
    if kind == "object":
        return "dictionary"
    return kind


def default_of(key, prop):
    if "default" not in prop:
        return "(none)"
    value = prop["default"]
    if isinstance(value, bool):
        return "`true`" if value else "`false`"
    if isinstance(value, dict):
        return ", ".join(f"`{k}` {v}" for k, v in value.items())
    if value in ("", []):
        return "(empty)"
    return f"`{value}`"


def allowed_of(prop):
    if "enum" in prop:
        return ", ".join(f"`{v}`" if v else "(empty)" for v in prop["enum"])
    items = prop.get("items", {})
    if "enum" in items:
        return "any of " + ", ".join(f"`{v}`" for v in items["enum"])
    low, high = prop.get("minimum"), prop.get("maximum")
    if low is not None and high is not None:
        return f"{low}–{high}"
    if low is not None:
        return f"{low} or more"
    return ""


def cell(text):
    return text.replace("|", "\\|").replace("\n", " ")


def describe(text):
    """Commands like -escrow in code style, so they don't break at the dash."""
    return re.sub(r"(?<![\w`-])(-[a-zA-Z][a-zA-Z-]*)", r"`\1`", text)


def render():
    props = json.loads(SCHEMA.read_text())["properties"]
    listed = [k for _, keys in SECTIONS for k in keys]
    missing = sorted(set(props) - set(listed))
    unknown = sorted(set(listed) - set(props))
    if missing or unknown:
        sys.exit(f"gen-settings-doc: not in SECTIONS: {missing}; "
                 f"not in the schema: {unknown}")
    out = [
        "<!-- Generated by .github/scripts/gen-settings-doc.py from",
        "     Profile Manifests/com.joshua-d-miller.macoslaps.json.",
        "     Edit the manifest, then run the script. -->",
        "# Settings reference",
        "",
        "Every setting macOSLAPS 4.0 reads, with its built-in default. "
        "Deliver them in a configuration profile for the preference domain "
        "`com.joshua-d-miller.macoslaps` (the 3.x domain "
        "`edu.psu.macoslaps` still works through 4.x). Leave a key out to "
        "use its default.",
        "",
        "!!! tip \"Check what a Mac actually uses\"",
        "    `sudo macOSLAPS -showConfig` prints every setting, its value "
        "and where it came from (managed profile, local file or default). "
        "`FirstPass` is never printed.",
        "",
        "The same list is in the repository as a "
        "[Jamf Pro custom schema and an iMazing Profile Editor manifest]"
        "(https://github.com/joshua-d-miller/macOSLAPS/tree/4.0.0.950/"
        "Profile%20Manifests), and as an "
        "[example plist](https://github.com/joshua-d-miller/macOSLAPS/blob/"
        "4.0.0.950/PLIST%20Example/com.joshua-d-miller.macoslaps.plist).",
        "",
    ]
    for title, keys in SECTIONS:
        out += [f"## {title}", "",
                "| Key | Type | Default | Values | What it does |",
                "|---|---|---|---|---|"]
        for key in keys:
            p = props[key]
            out.append(
                f"| `{key}` | {type_of(p)} | {cell(default_of(key, p))} | "
                f"{cell(allowed_of(p))} | {cell(describe(p.get('description', '')))} |")
        out.append("")
    return "\n".join(out)


# ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: #
# -------- #
# | Main | #
# -------- #
# Write the page, or with --check compare it with the committed one.      #
if __name__ == "__main__":
    page = render()
    if "--check" in sys.argv:
        if not PAGE.exists() or PAGE.read_text() != page:
            sys.exit("docs/settings.md is out of date: run "
                     "python3 .github/scripts/gen-settings-doc.py")
        print("docs/settings.md is up to date")
    else:
        PAGE.write_text(page)
        print(f"wrote {PAGE.relative_to(ROOT)}")
